name: Social Copy Generator
on:
  pull_request:
    types: [opened, synchronize]

jobs:
  generate-social-copy:
    runs-on: ubuntu-latest
    steps:
      - name: Checkout code
        uses: actions/checkout@v4

      - name: Initialize comment
        uses: thollander/actions-comment-pull-request@e4a76dd2b0a3c2027c3fd84147a67c22ee4c90fa
        id: init_comment
        with:
          message: |
            ## 📣 Generate Social Media Copies

            Check the box below to generate Twitter/X, LinkedIn, and Blog Post content for this PR:

            - [ ] Generate social media copies

            > This will analyze the PR diff and create engaging social media content using Claude Code.
          github-token: ${{ secrets.GITHUB_TOKEN }}
          pr-number: ${{ github.event.pull_request.number }}
          comment-tag: social-copy-init

      - name: Monitor for checkbox interaction
        uses: actions/github-script@v7
        id: monitor_checkbox
        with:
          github-token: ${{ secrets.GITHUB_TOKEN }}
          script: |
            const { owner, repo, number } = context.issue;
            const commentTag = 'social-copy-init';

            // Wait for checkbox to be checked
            let checkboxChecked = false;
            while (!checkboxChecked) {
              const comments = await github.rest.issues.listComments({
                owner,
                repo,
                issue_number: number
              });

              const comment = comments.data.find(c => 
                c.body.includes(commentTag) && 
                c.body.includes('Generate social media copies') &&
                c.body.includes('[x] Generate social media copies')
              );

              if (comment) {
                checkboxChecked = true;

                // Update comment to "Generating..."
                await github.rest.issues.updateComment({
                  owner,
                  repo,
                  comment_id: comment.id,
                  body: `
                    ## 📣 Generate Social Media Copies

                    Generating social media copies...

                    > Analyzing PR diff with Claude Code...
                  `
                });

                // Store comment ID for later updates
                core.setOutput('comment_id', comment.id);
              }

              // Wait before checking again
              await new Promise(r => setTimeout(r, 5000));
            }

      - name: Run Claude Code analysis
        uses: anthropics/claude-code-action@v1
        id: claude_analysis
        with:
          anthropic_api_key: ${{ secrets.ANTHROPIC_API_KEY }}
          claude_code_oauth_token: ${{ secrets.CLAUDE_CODE_OAUTH_TOKEN }}
          trigger_phrase: "Generate social media copies"
          prompt: |
            You are an expert content creator. Based on the PR diff, generate:

            1. A Twitter/X post (max 280 characters)
            2. A LinkedIn post (300-500 characters)
            3. A blog post title and intro paragraph (150-200 words)

            Format your response as:

            ### Twitter/X
            [Your tweet here]

            ### LinkedIn
            [Your LinkedIn post here]

            ### Blog Post
            **Title:** [Blog post title]

            [Intro paragraph]

            Include hashtags where appropriate and make the content engaging and professional.
          settings: |
            {
              "include_comments_by_actor": true,
              "exclude_comments_by_actor": ["github-actions[bot]"],
              "allowed_bots": ["github-actions[bot]"]
            }

      - name: Update comment with results
        uses: thollander/actions-comment-pull-request@e4a76dd2b0a3c2027c3fd84147a67c22ee4c90fa
        with:
          message: |
            ## 📣 Generate Social Media Copies

            ${{
              steps.claude_analysis.outputs.structured_output
            }}

            ---

            - [ ] Regenerate social media copies
          github-token: ${{ secrets.GITHUB_TOKEN }}
          pr-number: ${{ github.event.pull_request.number }}
          comment-tag: social-copy-results
          mode: update

      - name: Handle regeneration
        uses: actions/github-script@v7
        if: always()
        with:
          github-token: ${{ secrets.GITHUB_TOKEN }}
          script: |
            const { owner, repo, number } = context.issue;
            const commentTag = 'social-copy-results';

            // Check if user wants to regenerate
            const comments = await github.rest.issues.listComments({
              owner,
              repo,
              issue_number: number
            });

            const comment = comments.data.find(c => 
              c.body.includes(commentTag) && 
              c.body.includes('[x] Regenerate social media copies')
            );

            if (comment) {
              // Update comment to "Generating..."
              await github.rest.issues.updateComment({
                owner,
                repo,
                comment_id: comment.id,
                body: `
                  ## 📣 Generate Social Media Copies

                  Generating social media copies...

                  > Analyzing PR diff with Claude Code...
                `
              });

              // Trigger regeneration logic here
              // This would require additional workflow setup
            }
